/**
 * fetch-works.service
 * @author Malik Tillman
 *
 * 2020
 * */



/* Determine environment */
const production = true;
class FetchWorksService {
    constructor(http) {
        this.http = http;
        /* Main API endpoint */
        this.hostUrl = 'api.maliktillman.com';
        /* Cache */
        this._worksListCache = [];
        this._projectsCache = [];
        /* List of cached ids */
        this.cachedIDs = [];
        /* List of cached types */
        this.cachedMetaTypes = [];
        /* Records if works list is fully cached */
        this._isWorksListCached = false;
        /**
         * GetWorksListByIDs
         * Resolves work's list by ID
         * No caching
         * */
        this.getWorksListByIds = (ids) => {
            return new Promise(resolve => {
                this.http.get(`https://${this.hostUrl}/work-list_by-ids/${ids.join(',')}`)
                    .subscribe((data) => {
                    resolve(data);
                });
            });
        };
    }
    /**
     * GetWorksList
     * Resolves full work list.
     * */
    getWorksList() {
        return new Promise(resolve => {
            /* Resolve cached data */
            if (this._isWorksListCached)
                resolve(this._worksListCache);
            /* Fetch data and cache */
            else
                this.http.get(`https://${this.hostUrl}/work-list`)
                    .subscribe((data) => {
                    /* Cache data */
                    this._worksListCache = data;
                    this._isWorksListCached = true;
                    /* Return data */
                    resolve(data);
                });
        });
    }
    /**
     * GetProject
     * Returns project data, querying using specified ID
     * */
    getProject(id) {
        return new Promise(resolve => {
            /* Check if project is cached */
            if (this.cachedIDs.includes(id))
                /* Return cached data */
                resolve(this._projectsCache.find(project => project.id == id));
            else {
                /* Add project id to cached list */
                this.cachedIDs.push(id);
                /* Fetch data */
                this.http.get(`https://${this.hostUrl}/works/${id}`).subscribe((data) => {
                    /* Add project to cache */
                    this._projectsCache.push(data);
                    /* Return data */
                    resolve(data);
                });
            }
        });
    }
    /**
     * GetWorksListByType
     * Resolves work's meta data by type
     * */
    getWorksListByType(types) {
        return new Promise(resolve => {
            /* Types that have not been cached */
            let queryTypes = [];
            if (!this._isWorksListCached) {
                /* Add to cached list */
                types.forEach(type => {
                    if (!this.cachedMetaTypes.includes(type)) {
                        this.cachedMetaTypes.push(type);
                        queryTypes.push(type);
                    }
                });
            }
            /* Query uncached types */
            if (queryTypes.length > 0) {
                /* Fetch data */
                this.http.get(`https://${this.hostUrl}/work-list/${queryTypes.join(',')}`)
                    .subscribe((data) => {
                    /* Push data to cache */
                    data.forEach(metaProject => {
                        this._worksListCache.push(metaProject);
                    });
                    /* Return Data */
                    resolve(this._worksListCache.filter(metaWork => types.includes(metaWork.category)));
                });
            }
            else
                /* Return cached data */
                resolve(this._worksListCache.filter(metaWork => types.includes(metaWork.category)));
        });
    }
}
